class Trie {
    class Node { Node[] children = new Node[26]; boolean isEnd; }
    private Node root = new Node();
    public void insert(String word) {
        Node curr = root;
        for (char c : word.toCharArray()) {
            int idx = c - 'a';
            if (curr.children[idx] == null) curr.children[idx] = new Node();
            curr = curr.children[idx];
        }
        curr.isEnd = true;
    }
    public boolean search(String word) {
        Node node = find(word);
        return node != null && node.isEnd;
    }
    public boolean startsWith(String prefix) {
        return find(prefix) != null;
    }
    private Node find(String s) {
        Node curr = root;
        for (char c : s.toCharArray()) {
            int idx = c - 'a';
            if (curr.children[idx] == null) return null;
            curr = curr.children[idx];
        }
        return curr;
    }
}

public List<String> findWords(char[][] board, String[] words) {
    TrieNode root = buildTrie(words);
    List<String> result = new ArrayList<>();
    for (int i = 0; i < board.length; i++)
        for (int j = 0; j < board[0].length; j++)
            dfs(board, i, j, root, result);
    return result;
}
class TrieNode { TrieNode[] children = new TrieNode[26]; String word; }
private TrieNode buildTrie(String[] words) {
    TrieNode root = new TrieNode();
    for (String w : words) {
        TrieNode curr = root;
        for (char c : w.toCharArray()) {
            int idx = c - 'a';
            if (curr.children[idx] == null) curr.children[idx] = new TrieNode();
            curr = curr.children[idx];
        }
        curr.word = w;
    }
    return root;
}
private void dfs(char[][] board, int r, int c, TrieNode node, List<String> result) {
    if (r < 0 || c < 0 || r >= board.length || c >= board[0].length || board[r][c] == '#') return;
    char ch = board[r][c];
    TrieNode next = node.children[ch - 'a'];
    if (next == null) return;
    if (next.word != null) { result.add(next.word); next.word = null; }
    board[r][c] = '#';
    dfs(board, r + 1, c, next, result);
    dfs(board, r - 1, c, next, result);
    dfs(board, r, c + 1, next, result);
    dfs(board, r, c - 1, next, result);
    board[r][c] = ch;
}

class BitTrie {
    class Node { Node[] children = new Node[2]; }
    private Node root = new Node();
    public void insert(int num) {
        Node curr = root;
        for (int i = 31; i >= 0; i--) {
            int bit = (num >> i) & 1;
            if (curr.children[bit] == null) curr.children[bit] = new Node();
            curr = curr.children[bit];
        }
    }
    public int maxXor(int num) {
        Node curr = root;
        int result = 0;
        for (int i = 31; i >= 0; i--) {
            int bit = (num >> i) & 1;
            int desired = 1 - bit;
            if (curr.children[desired] != null) {
                result |= (1 << i);
                curr = curr.children[desired];
            } else {
                curr = curr.children[bit];
            }
        }
        return result;
    }
}

public List<List<String>> suggestedProducts(String[] products, String searchWord) {
    Arrays.sort(products);
    List<List<String>> result = new ArrayList<>();
    String prefix = "";
    for (char c : searchWord.toCharArray()) {
        prefix += c;
        List<String> matches = new ArrayList<>();
        int idx = Arrays.binarySearch(products, prefix);
        if (idx < 0) idx = -(idx + 1);
        for (int i = idx; i < Math.min(products.length, idx + 3); i++) {
            if (products[i].startsWith(prefix)) matches.add(products[i]);
        }
        result.add(matches);
    }
    return result;
}
